<script setup lang="ts">
import { unwrap } from '~/api/client'; import { displayError } from '~/utils/errors'; import { formatDate, statusLabel } from '~/utils/format';
definePageMeta({ middleware: 'auth' }); const api = useMarketplaceApi(); const route = useRoute(); const cartApi = useCart();
const { data, error, status, refresh } = await useAsyncData(`case-${route.params.id}`, async () => { if (!cartApi.account.value) await cartApi.load(); return unwrap(await api.GET('/buyer-accounts/{buyerAccountId}/cases/{caseId}', { params: { path: { buyerAccountId: cartApi.account.value!.id, caseId: String(route.params.id) } }, cache: 'no-store' })); }, { server: false });
useSeoMeta({ title: 'Status komplain — Niaga' });
</script>
<template><main id="main-content" class="page-shell"><BuyerNav/><ApiState :pending="status === 'idle' || status === 'pending'" :error="error ? displayError(error) : null" @retry="refresh"><article v-if="data" class="surface"><div class="section-heading"><div><p class="eyebrow">Komplain {{ data.id.slice(0,8) }}</p><h1>{{ statusLabel(data.kind) }}</h1></div><span class="badge" :class="{ 'badge--warning': data.state === 'OPEN' }">{{ statusLabel(data.state) }}</span></div><ol class="timeline"><li><span/><div><strong>Komplain dibuka</strong><p>{{ data.reason }}</p><small>{{ formatDate(data.created_at) }}</small></div></li><li v-if="data.resolution"><span/><div><strong>Keputusan</strong><p>{{ data.resolution }}</p></div></li><li v-else><span/><div><strong>Menunggu peninjauan</strong><p>Tim akan memeriksa transaksi dan informasi terkait.</p></div></li></ol><p class="muted">Jika keputusan menghasilkan refund, status dana ditampilkan terpisah pada halaman refund.</p><NuxtLink class="button button--secondary" to="/akun/refund">Lihat refund</NuxtLink></article></ApiState></main></template>
